class CodeCopier extends HTMLElement{constructor(){super(),this.copyButton=this.querySelector("[data-js-btn]"),this.copyText=this.querySelector("[data-js-code]"),this.successMessage=this.copyButton.getAttribute("data-success")||"Copied!",this.defaultMessage=this.copyButton.getAttribute("data-default")||"Copy",this.copyButton.innerHTML=this.defaultMessage,this.copyButton.addEventListener("click",this.copyCode.bind(this))}copyCode(t){t.preventDefault(),this.copyText.select(),this.copyText.setSelectionRange(0,99999),navigator.clipboard.writeText(this.copyText.value).then(()=>{this.showTooltip(this.successMessage)}).catch(()=>{this.showTooltip(this.successMessage)})}showTooltip(t){this.copyButton.innerHTML=t,setTimeout(()=>{this.copyButton.innerHTML=this.defaultMessage},2e3)}}customElements.define("code-copier",CodeCopier);